// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address admin, bool access, address account, uint256 tokenId) public {
        vm.assume(account != address(0));
        c.adjustAdminAccess(admin, access);
        assertTrue(c.balanceOf(account, tokenId) == 0);
    }
}

